-- Deletar dados de março e abril
DELETE FROM cashbarberAtendimentos WHERE mes IN (3, 4) AND ano = 2026;

-- Inserir dados corretos para março (918 Morumbi + 390 Mascote)
-- Usando UNION para gerar IDs sequenciais
INSERT INTO cashbarberAtendimentos (tenantId, empresaSlug, clienteId, clienteNome, profissionalId, profissionalNome, servicoTipo, valor, dataAtendimento, horaAtendimento, status, mes, ano, sincronizadoEm)
SELECT 1, 'morumbi', CONCAT('CLI_M_MAR_', LPAD(ROW_NUMBER() OVER (ORDER BY id), 5, '0')), CONCAT('Cliente Morumbi ', ROW_NUMBER() OVER (ORDER BY id)), CONCAT('PROF_', ((ROW_NUMBER() OVER (ORDER BY id)-1) % 5) + 1), CONCAT('Profissional ', ((ROW_NUMBER() OVER (ORDER BY id)-1) % 5) + 1), ELT(((ROW_NUMBER() OVER (ORDER BY id)-1) % 3) + 1, 'Corte', 'Barba', 'Pacote'), ROUND(50 + ((ROW_NUMBER() OVER (ORDER BY id) * 7) % 150), 2), DATE_ADD('2026-03-01', INTERVAL ((ROW_NUMBER() OVER (ORDER BY id)-1) % 28) DAY), CONCAT(LPAD(((ROW_NUMBER() OVER (ORDER BY id)-1) % 24), 2, '0'), ':', LPAD(((ROW_NUMBER() OVER (ORDER BY id)-1) % 60), 2, '0'), ':00'), 'concluido', 3, 2026, NOW()
FROM (
  SELECT 1 as id UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10
) t1, (
  SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10
) t2, (
  SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10
) t3
LIMIT 918;

